    private val paths = HashMap<String, Path>()
    private val vectors = HashMap<String, ImageVector>()

    /** The icon [name] scaled to a [size] square at the origin, for a View canvas. */
    fun path(name: String, size: Float): Path {
        val base = paths.getOrPut(name) { PathParser.createPathFromPathData(data.getValue(name)) }
        return Path(base).apply { transform(Matrix().apply { setScale(size / BOX, size / BOX) }) }
    }

    /** The icon [name] for Compose, drawn in the tint of the Icon that shows it. */
    fun vector(name: String): ImageVector = vectors.getOrPut(name) {
        ImageVector.Builder(name, 24.dp, 24.dp, BOX, BOX)
            .addPath(addPathNodes(data.getValue(name)), fill = SolidColor(androidx.compose.ui.graphics.Color.Black))
            .build()
    }
}
